/**
 * A casca do pomelo — porte de `componentes/viz/pomelo.js`.
 *
 * O pomelo cai de dez metros e não racha. O truque não é a casca ser grossa: é
 * ela ser uma espuma de densidade GRADUAL — densa por fora, cada vez mais aberta
 * por dentro. O gradiente espalha o impacto ao longo da espessura em vez de
 * entregá-lo de uma vez à polpa.
 *
 * A cena mostra as duas coisas ao mesmo tempo: a fruta caindo e o corte da casca
 * com os poros abrindo camada a camada. A barra à direita é a força que chega à
 * polpa — quem decide se a fruta sobrevive.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  MATERIAIS,
  numeroDe,
  paleta,
  retangulo,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const CAMADAS = 10;

const pomelo: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const graduacao = numeroDe(valores, 'gr', 0);
    const forca = numeroDe(info, 'forca', 0);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'A casca que absorve a queda');

    const chaoY = A * 0.8;

    // O chão.
    ctx.fillStyle = MATERIAIS.terra;
    ctx.fillRect(0, chaoY, L, A - chaoY);
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(0, chaoY);
    ctx.lineTo(L, chaoY);
    ctx.stroke();

    // A queda, em ciclo: 70% do tempo caindo, o resto no chão.
    const R = limitar(Math.min(L, A) * 0.11, 24, 46);
    const cx = L * 0.28;
    const topo = A * 0.2;
    const pouso = chaoY - R;
    const fase = (t * 0.5) % 1;
    const y = fase < 0.7 ? topo + (pouso - topo) * (fase / 0.7) : pouso;
    const impacto = fase >= 0.7 && fase < 0.9;

    if (fase < 0.7) {
      ctx.strokeStyle = cor.trilho;
      ctx.lineWidth = 1.5;
      for (const dx of [-14, 0, 14]) {
        ctx.beginPath();
        ctx.moveTo(cx + dx, y - R - 6);
        ctx.lineTo(cx + dx, y - R - 24);
        ctx.stroke();
      }
    }

    // A fruta: casca espessa, e a polpa que se quer salvar.
    ctx.fillStyle = '#c9d84a';
    ctx.beginPath();
    ctx.arc(cx, y, R, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeStyle = '#9caa2f';
    ctx.lineWidth = R * 0.17;
    ctx.beginPath();
    ctx.arc(cx, y, R * 0.9, 0, Math.PI * 2);
    ctx.stroke();

    ctx.fillStyle = ok ? '#e9b84a' : cor.erro;
    ctx.beginPath();
    ctx.arc(cx, y, R * 0.64, 0, Math.PI * 2);
    ctx.fill();

    if (!ok && impacto) {
      ctx.strokeStyle = '#7a1a12';
      ctx.lineWidth = 2;
      for (let i = 0; i < 5; i++) {
        const angulo = (i / 5) * Math.PI * 2;
        ctx.beginPath();
        ctx.moveTo(cx, y);
        ctx.lineTo(cx + Math.cos(angulo) * R * 0.64, y + Math.sin(angulo) * R * 0.64);
        ctx.stroke();
      }
    }

    if (impacto) {
      ctx.strokeStyle = ok ? cor.verde : cor.erro;
      ctx.lineWidth = 2;
      for (let i = 0; i < 3; i++) {
        ctx.beginPath();
        ctx.ellipse(cx, chaoY, 22 + i * 20, 6 + i * 4, 0, Math.PI, Math.PI * 2);
        ctx.stroke();
      }
    }

    // O corte da casca: cada faixa é uma camada da espuma, e os pontos são os
    // poros. Quanto mais fundo, menos denso — é a graduação em pessoa.
    const ix = L * 0.56;
    const iy = A * 0.18;
    const iw = L * 0.3;
    const ih = A * 0.52;

    retangulo(ctx, ix, iy, iw, ih, 6, cor.palha, cor.trilho, 1.2);
    texto(ctx, 'corte da casca', ix + iw / 2, iy - A * 0.035, limitar(A * 0.038, 9, 12), {
      cor: cor.fraco,
      peso: 700,
    });

    const alturaFaixa = (ih - 12) / CAMADAS;
    for (let i = 0; i < CAMADAS; i++) {
      const fundura = i / (CAMADAS - 1);
      const densidade = 1 - fundura * (graduacao / 100);
      const ry = iy + 6 + i * alturaFaixa;

      ctx.fillStyle = `rgb(176 125 16 / ${(0.18 + 0.5 * densidade) * 100}%)`;
      ctx.fillRect(ix + 3, ry, iw - 6, alturaFaixa - 1);

      // Poro maior onde a espuma é mais aberta.
      ctx.fillStyle = cor.fundo;
      const poros = Math.round(2 + (1 - densidade) * 5);
      for (let b = 0; b < poros; b++) {
        const bx = ix + 10 + (b * (iw - 20)) / poros + (i % 2) * 4;
        ctx.beginPath();
        ctx.arc(bx, ry + alturaFaixa / 2, 1.4 + (1 - densidade) * 2.6, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // A barra da força que chega à polpa.
    const gx = L - 14;
    const gy = A * 0.18;
    const gh = A * 0.62;
    retangulo(ctx, gx, gy, 9, gh, 4, cor.trilho);
    const preenchida = (gh * limitar(forca, 0, 100)) / 100;
    retangulo(ctx, gx, gy + gh - preenchida, 9, preenchida, 4, ok ? cor.verde : cor.erro);

    texto(
      ctx,
      `graduação ${Math.round(graduacao)}% · força na polpa ${Math.round(forca)}%`,
      L / 2,
      A * 0.95,
      limitar(A * 0.044, 10, 14),
      { cor: ok ? cor.verde : cor.fraco, peso: 700 },
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default pomelo;
